T = {
'card5_title': ("50 PCs to Configure", "50 equipos que configurar"),
'card6_opt0_res0': ("Certified! {0.SimFirstName}'s résumé just got more valuable.\n\nDid you know? Cisco's CCNA is in high demand for networking jobs, and you can prepare for it with Packet Tracer.", "¡Certificado! El currículum de {0.SimFirstName} gana valor.\n\n¿Lo sabías? El CCNA de Cisco está muy solicitado en los empleos de redes, y se prepara con Packet Tracer."),
'card6_opt0_res1': ("Missed it by a hair. {0.SimFirstName} will retake it.\n\nDid you know? Hands-on labs (Packet Tracer, VMs) beat memorizing theory.", "Por muy poco. {0.SimFirstName} volverá a presentarse.\n\n¿Lo sabías? Los laboratorios prácticos (Packet Tracer, máquinas virtuales) valen más que memorizar la teoría."),
'card6_opt0': ("Study and take the exam", "Estudiar y hacer el examen"),
'card6_opt1_res0': ("The boss notes that {0.SimFirstName} isn't very motivated.\n\nDid you know? In IT you keep learning all your life: technology changes fast.", "El jefe nota que {0.SimFirstName} no está muy motivado.\n\n¿Lo sabías? En informática se aprende toda la vida: la tecnología cambia rápido."),
'card6_opt1': ("Decline, no time", "Rechazar, no hay tiempo"),
'card6_text': ("The company offers to pay for a certification for {0.SimFirstName} (CCNA, Security+…). It means studying in the evenings.", "La empresa ofrece pagarle a {0.SimFirstName} una certificación (CCNA, Security+…). Habrá que estudiar por las noches."),
'card6_title': ("The Certification", "La certificación"),
'card7_opt0_res0': ("It was a trap: the drive had a virus and the network is down for an hour!\n\nDid you know? Abandoned USB drives are a classic hacker trick (the \"USB drop\" attack).", "Era una trampa: la memoria tenía un virus y la red queda bloqueada una hora.\n\n¿Lo sabías? Las memorias USB abandonadas son una trampa clásica de los atacantes (el ataque «USB drop»)."),
'card7_opt0_res1': ("It contained… vacation photos. Phew.\n\nDid you know? You got lucky: never plug in an unknown drive.", "Contenía… fotos de vacaciones. Uf.\n\n¿Lo sabías? Has tenido suerte: nunca se conecta una memoria desconocida."),
'card7_opt0': ("Plug it in to see", "Conectarla para ver"),
'card7_opt1_res0': ("Good reflex! It was a test set up by management. {0.SimFirstName} is held up as an example.\n\nDid you know? User awareness is one of the best protections against attacks.", "¡Buen reflejo! Era una prueba organizada por la dirección. Ponen a {0.SimFirstName} como ejemplo.\n\n¿Lo sabías? La concienciación de los usuarios es una de las mejores protecciones contra los ataques."),
'card7_opt1': ("Hand it to the security team", "Dársela al equipo de seguridad"),
'card7_text': ("{0.SimFirstName} finds a USB drive labeled \"Salaries 2026\" in the parking lot.", "{0.SimFirstName} encuentra en el aparcamiento una memoria USB con la etiqueta «Salarios 2026»."),
'card7_title': ("The Mystery USB Drive", "La memoria USB misteriosa"),
'card8_opt0_res0': ("It reboots and everything works… for today.\n\nDid you know? If you don't look for the cause, the outage comes back. That's the difference between an incident and a problem (ITIL).", "Se reinicia y todo funciona… por hoy.\n\n¿Lo sabías? Si no se busca la causa, la avería vuelve. Es la diferencia entre un incidente y un problema (ITIL)."),
'card8_opt0_res1': ("The disk was dying: after the reboot, the server doesn't come back!\n\nDid you know? Before rebooting, read the logs to understand what's going on.", "El disco se estaba muriendo: tras el reinicio, el servidor ya no arranca.\n\n¿Lo sabías? Antes de reiniciar, se revisan los registros (logs) para entender qué pasa."),
'card8_opt0': ("Reboot the server right away", "Reiniciar el servidor ya"),
'card8_opt1_res0': ("{0.SimFirstName} finds a failing disk in the RAID and replaces it without shutting down the server!\n\nDid you know? RAID 1 copies data onto 2 disks: if one breaks, the other takes over.", "¡{0.SimFirstName} encuentra un disco defectuoso en el RAID y lo cambia sin apagar el servidor!\n\n¿Lo sabías? El RAID 1 copia los datos en 2 discos: si uno se rompe, el otro toma el relevo."),
'card8_opt1_res1': ("The analysis takes too long and users are getting impatient.\n\nDid you know? A monitoring tool (like Zabbix or Nagios) warns you before the outage happens.", "El análisis tarda demasiado y los usuarios se impacientan.\n\n¿Lo sabías? Una herramienta de supervisión (como Zabbix o Nagios) avisa antes de que llegue la avería."),
'card8_opt1': ("Read the logs before acting", "Leer los logs antes de actuar"),
'card8_text': ("The file server isn't responding: the whole company is stuck and {0.SimFirstName}'s phone won't stop ringing.", "El servidor de archivos no responde: toda la empresa está bloqueada y el teléfono de {0.SimFirstName} no para de sonar."),
'card8_title': ("The Server Is Down", "El servidor no responde"),
'card9_opt0_res0': ("The update crashes the mail server. {0.SimFirstName} stays late to fix it.\n\nDid you know? Avoid changes on Friday evenings: if something breaks, nobody is around to fix it.", "La actualización tumba el correo. {0.SimFirstName} se queda hasta tarde para repararlo.\n\n¿Lo sabías? Se evitan los cambios el viernes por la tarde: si hay un problema, no hay nadie para arreglarlo."),
'card9_opt0_res1': ("Everything went fine, this time.\n\nDid you know? A good practice is to test updates on a test server first.", "Todo ha ido bien, esta vez.\n\n¿Lo sabías? Una buena práctica es probar las actualizaciones primero en un servidor de pruebas."),
'card9_opt0': ("Install it now", "Instalarla ahora"),
'card9_opt1_res0': ("Monday morning, everything goes smoothly, and the rollback plan was ready.\n\nDid you know? Before any change, always plan how to roll back (VM snapshot, backup).", "El lunes por la mañana todo va bien, y el plan de vuelta atrás estaba listo.\n\n¿Lo sabías? Antes de un cambio, siempre se prevé cómo volver atrás (snapshot de la VM, copia de seguridad)."),
'card9_opt1_res1': ("The boss thinks {0.SimFirstName} was too cautious.\n\nDid you know? When a vulnerability is critical, you sometimes have to patch urgently.", "El jefe cree que {0.SimFirstName} ha sido demasiado prudente.\n\n¿Lo sabías? Cuando un fallo es crítico, a veces hay que corregirlo de urgencia."),
'card9_opt1': ("Schedule it for Monday with a plan B", "Programarla el lunes con un plan B"),
'card9_text': ("It's 4 PM on a Friday. A major update needs to be installed on the mail server.", "Son las 16:00 de un viernes. Hay que instalar una actualización importante en el servidor de correo."),
'card9_title': ("Friday Update", "Actualización del viernes"),
'card10_opt0_res0': ("Flawless result! Every cable is labeled.\n\nDid you know? A tidy, labeled rack saves a huge amount of time during outages.", "¡Resultado impecable! Cada cable está identificado.\n\n¿Lo sabías? Un rack ordenado y etiquetado ahorra muchísimo tiempo cuando hay averías."),
'card10_opt0_res1': ("{0.SimFirstName} unplugged the wrong cable: accounting is cut off from the network!\n\nDid you know? You warn users and work outside business hours.", "{0.SimFirstName} ha desconectado el cable equivocado: ¡contabilidad se queda sin red!\n\n¿Lo sabías? Se avisa a los usuarios y se interviene fuera del horario laboral."),
'card10_opt0': ("Rewire and label everything", "Recablear y etiquetarlo todo"),
'card10_opt1_res0': ("The day someone needs to find a cable, nobody can.\n\nDid you know? Network documentation (diagram, addressing plan) is part of an admin's job.", "El día que hay que encontrar un cable, nadie se aclara.\n\n¿Lo sabías? La documentación de red (esquema, plan de direccionamiento) forma parte del trabajo de un administrador."),
'card10_opt1': ("Leave it, it works", "Dejarlo así, funciona"),
'card10_text': ("The patch panel looks like a plate of spaghetti: cables everywhere, no labels.", "El rack de cableado parece un plato de espaguetis: cables por todas partes y sin etiquetas."),
'card10_title': ("The Spaghetti Plate", "El plato de espaguetis"),
'card11_opt0_res0': ("The restore works perfectly. Management is reassured.\n\nDid you know? Regularly testing restores is the only way to be sure backups work.", "La restauración funciona a la perfección. La dirección se queda tranquila.\n\n¿Lo sabías? Probar la restauración con regularidad es la única forma de asegurarse de que las copias funcionan."),
'card11_opt0_res1': ("The restore fails: the backup had been empty for 3 months! Luckily, it was caught in time.\n\nDid you know? That's why we test: better to find out now than on the day of a real outage.", "La restauración falla: ¡la copia llevaba 3 meses vacía! Por suerte, se ha visto a tiempo.\n\n¿Lo sabías? Por eso se prueba: mejor descubrirlo ahora que el día de una avería real."),
'card11_opt0': ("Run a real test restore", "Hacer una restauración de prueba real"),
'card11_opt1_res0': ("Management is satisfied.\n\nDid you know? A green light doesn't prove the data can be restored.", "La dirección está satisfecha.\n\n¿Lo sabías? Un indicador en verde no demuestra que los datos se puedan restaurar."),
'card11_opt1_res1': ("An auditor asks for a restore… and it fails. Very awkward.\n\nDid you know? A backup you've never tested isn't a real backup.", "Un auditor pide una restauración… y falla. Situación muy incómoda.\n\n¿Lo sabías? Una copia de seguridad que nunca se ha probado no es una copia de verdad."),
'card11_opt1': ("Show the all-green dashboard", "Enseñar el panel todo en verde"),
'card11_text': ("Management wants to check that the backups really work.", "La dirección quiere comprobar que las copias de seguridad funcionan de verdad."),
'card11_title': ("Surprise Backup Test", "Prueba sorpresa de las copias"),
'card12_opt0_res0': ("The network is cleanly separated: guests get Internet, but not the company's data.\n\nDid you know? A VLAN is a virtual network: on the same switch, you create networks that can't see each other.", "La red queda bien separada: los invitados tienen Internet, pero no los datos de la empresa.\n\n¿Lo sabías? Una VLAN es una red virtual: en el mismo switch se crean redes que no se ven entre sí."),
'card12_opt0_res1': ("Marketing complains to management, who asks for an explanation.\n\nDid you know? Explaining a technical choice simply to non-IT people is a key skill.", "Marketing se queja a la dirección, que pide explicaciones.\n\n¿Lo sabías? Saber explicar de forma sencilla una decisión técnica a quien no es informático es una competencia clave."),
'card12_opt0': ("Refuse and create an isolated guest VLAN", "Negarse y crear una VLAN de invitados aislada"),
'card12_opt1_res0': ("The presentations work.\n\nDid you know? You took a big risk: any visitor could see the files.", "Las presentaciones funcionan.\n\n¿Lo sabías? Has corrido un gran riesgo: cualquier visitante podía ver los archivos."),
'card12_opt1_res1': ("A visitor was able to open the HR folders…\n\nDid you know? The guest network is always separated from the internal network (VLAN + firewall rules).", "Un visitante ha podido abrir las carpetas de recursos humanos…\n\n¿Lo sabías? La red de invitados siempre se separa de la red interna (VLAN + reglas de cortafuegos)."),
'card12_opt1': ("Open access, it's easier", "Abrir el acceso, es más sencillo"),
'card12_text': ("Marketing wants visitors on the guest Wi-Fi to be able to reach the file server \"for presentations\".", "Marketing quiere que los visitantes del Wi-Fi de invitados puedan acceder al servidor de archivos «para las presentaciones»."),
'card12_title': ("The Visitors' Wi-Fi", "El Wi-Fi de los visitantes"),
'card13_opt0_res0': ("Budget approved! Management congratulates {0.SimFirstName} and pays a bonus.\n\nDid you know? End-of-life hardware no longer gets security updates: that's a strong argument.", "¡Presupuesto aprobado! La dirección felicita a {0.SimFirstName} y le da una prima.\n\n¿Lo sabías? Un equipo al final de su vida útil ya no recibe actualizaciones de seguridad: es un argumento de peso."),
'card13_opt0_res1': ("Rejected, but management liked the presentation.\n\nDid you know? A good proposal compares the purchase cost with the cost of an outage.", "Rechazado, pero a la dirección le ha gustado la presentación.\n\n¿Lo sabías? Un buen informe compara el coste de compra con el coste de una avería."),
'card13_opt0': ("Present a costed proposal", "Presentar un informe con cifras"),
'card13_opt1_res0': ("Budget rejected. The old switches will have to last another year.\n\nDid you know? To convince people, you need numbers: cost, risk, benefit.", "Presupuesto rechazado. Los viejos switches tendrán que aguantar otro año.\n\n¿Lo sabías? Para convencer hacen falta cifras: coste, riesgo, beneficio."),
'card13_opt1': ("Send a quick email", "Enviar un simple correo"),
'card13_text': ("{0.SimFirstName} has to convince management to buy new switches: the old ones are 12 years old.", "{0.SimFirstName} tiene que convencer a la dirección de comprar switches nuevos: los viejos tienen 12 años."),
'card13_title': ("The Switch Budget", "El presupuesto de los switches"),
'card14_opt0_res0': ("The VPN is back in 15 minutes. The sales team loves {0.SimFirstName}.\n\nDid you know? A VPN creates an encrypted tunnel to reach the company network from outside.", "La VPN vuelve en 15 minutos. Los comerciales adoran a {0.SimFirstName}.\n\n¿Lo sabías? Una VPN crea un túnel cifrado para acceder a la red de la empresa desde fuera."),
'card14_opt0': ("Drop lunch and step in", "Dejar la comida e intervenir"),
'card14_opt1_res0': ("The VPN came back on its own. Lucky!\n\nDid you know? Being on call means being reachable outside working hours, and it's paid extra.", "La VPN ha vuelto sola. ¡Qué suerte!\n\n¿Lo sabías? Estar de guardia es estar localizable fuera del horario, y se paga aparte."),
'card14_opt1_res1': ("A big sale was lost during the outage.\n\nDid you know? On-call response time is often written into the contract (SLA).", "Se ha perdido una gran venta durante el corte.\n\n¿Lo sabías? El tiempo de respuesta de guardia suele figurar en el contrato (SLA)."),
'card14_opt1': ("Finish the sandwich first", "Terminar primero el bocadillo"),
'card14_text': ("The on-call phone rings during lunch: the VPN is down and the traveling sales reps are stuck.", "El teléfono de guardia suena durante la comida: la VPN no funciona y los comerciales de viaje están bloqueados."),
'card14_title': ("On Call: The VPN Is Down", "Guardia: la VPN ha caído"),
'card15_opt0_res0': ("Well done: the virus didn't have time to spread!\n\nDid you know? The first reflex when a machine is infected is to isolate it to protect the rest of the network.", "¡Bien hecho: el virus no ha tenido tiempo de propagarse!\n\n¿Lo sabías? Lo primero ante una infección es aislar la máquina para proteger el resto de la red."),
'card15_opt0': ("Disconnect their PC from the network immediately", "Aislar su equipo de la red inmediatamente"),
'card15_opt1_res0': ("It was ransomware. Three servers are encrypted…\n\nDid you know? Ransomware encrypts files and demands a ransom. You don't pay: you restore from backups.", "Era un ransomware. Tres servidores están cifrados…\n\n¿Lo sabías? Un ransomware cifra los archivos y pide un rescate. No se paga: se restauran las copias de seguridad."),
'card15_opt1_res1': ("False alarm: it was a real delivery link.\n\nDid you know? When in doubt, always report it. A false positive costs nothing.", "Falsa alarma: era un enlace de entrega real.\n\n¿Lo sabías? Ante la duda, siempre se avisa. Un falso positivo no cuesta nada."),
'card15_opt1': ("Tell them to reboot and forget it", "Decirle que reinicie y olvidarlo"),
'card15_text': ("A colleague clicked a link in an email saying \"Your parcel is on hold, pay €1.99\".", "Un compañero ha hecho clic en un enlace de un correo que dice «Tu paquete está retenido, paga 1,99 €»."),
'card15_title': ("Phishing Alert!", "¡Alerta de phishing!"),
'card16_opt0_res0': ("{0.SimFirstName} finds the real one: an admin account is logging in from the other side of the world!\n\nDid you know? A SOC (security operations center) watches the network 24/7 with a tool called a SIEM.", "{0.SimFirstName} encuentra la de verdad: ¡una cuenta de administrador se conecta desde el otro lado del mundo!\n\n¿Lo sabías? Un SOC (centro de operaciones de seguridad) vigila la red 24 horas con una herramienta llamada SIEM."),
'card16_opt0_res1': ("Too many alerts, {0.SimFirstName} doesn't have time to see them all.\n\nDid you know? Too many useless alerts is called \"alert fatigue\": analysts end up missing the real ones.", "Demasiadas alertas: {0.SimFirstName} no tiene tiempo de verlas todas.\n\n¿Lo sabías? El exceso de alertas inútiles se llama «fatiga de alertas»: los analistas acaban pasando por alto las reales."),
'card16_opt0': ("Analyze them one by one", "Analizarlas una por una"),
'card16_opt1_res0': ("The rule removes 490 false alerts. Only the real ones are left!\n\nDid you know? Tuning detection rules to reduce false positives is part of an analyst's job.", "La regla elimina 490 falsas alertas. ¡Solo quedan las reales!\n\n¿Lo sabías? Ajustar las reglas de detección para reducir los falsos positivos forma parte del trabajo del analista."),
'card16_opt1_res1': ("The rule also hid the real attack…\n\nDid you know? A filter that's too broad creates false negatives: real attacks you no longer see.", "La regla también ha ocultado el ataque real…\n\n¿Lo sabías? Un filtro demasiado amplio crea falsos negativos: ataques reales que ya no se ven."),
'card16_opt1': ("Create a rule to filter the noise", "Crear una regla para filtrar el ruido"),
'card16_text': ("The SOC dashboard shows 500 alerts. Most of them are probably false alarms.", "El panel del SOC muestra 500 alertas. La mayoría seguramente son falsas alarmas."),
'card16_title': ("500 Alerts at the SOC", "500 alertas en el SOC"),
'card17_opt0_res0': ("Nobody stopped them! The report makes the client tremble.\n\nDid you know? A pentest is always done with written authorization. Without it, it's illegal.", "¡Nadie le ha detenido! El informe hace temblar al cliente.\n\n¿Lo sabías? Un pentest siempre se hace con autorización por escrito. Sin ella, es ilegal."),
'card17_opt0_res1': ("Reception saw through {0.SimFirstName}'s disguise. That's a good result for the client too!\n\nDid you know? A failed test shows that the client's security works.", "La recepción ha desenmascarado a {0.SimFirstName}. ¡También es un buen resultado para el cliente!\n\n¿Lo sabías? Una prueba que falla demuestra que la seguridad del cliente funciona."),
'card17_opt0': ("Dress up as a pizza delivery person", "Disfrazarse de repartidor de pizza"),
'card17_opt1_res0': ("The Wi-Fi used old encryption: {0.SimFirstName} gets into the network in 10 minutes.\n\nDid you know? WEP encryption has been broken for a long time. Today we use WPA2 or WPA3.", "El Wi-Fi usaba un cifrado antiguo: {0.SimFirstName} entra en la red en 10 minutos.\n\n¿Lo sabías? El cifrado WEP está roto desde hace mucho. Hoy se usa WPA2 o WPA3."),
'card17_opt1_res1': ("The Wi-Fi is well protected. Nothing to report.\n\nDid you know? A long, complex Wi-Fi password makes attacks almost impossible.", "El Wi-Fi está bien protegido. Nada que señalar.\n\n¿Lo sabías? Una contraseña Wi-Fi larga y compleja hace los ataques casi imposibles."),
'card17_opt1': ("Test the Wi-Fi from the parking lot", "Probar el Wi-Fi desde el aparcamiento"),
'card17_text': ("Physical intrusion test: {0.SimFirstName} has to get into a client's building without a badge (with their written authorization, of course).", "Prueba de intrusión física: {0.SimFirstName} debe entrar en el edificio de un cliente sin tarjeta (con su autorización por escrito, claro)."),
'card17_title': ("Mission: Get In Without a Badge", "Misión: entrar sin tarjeta"),
'card18_opt0_res0': ("The company fixes the flaw and publicly thanks {0.SimFirstName}.\n\nDid you know? Warning the company without exploiting the flaw is called responsible disclosure.", "La empresa corrige el fallo y agradece públicamente a {0.SimFirstName}.\n\n¿Lo sabías? Avisar a la empresa sin explotar el fallo se llama divulgación responsable."),
'card18_opt0': ("Quietly report it to the company", "Avisar discretamente a la empresa"),
'card18_opt1_res0': ("Management is horrified: exploiting a flaw without authorization is illegal! Official warning.\n\nDid you know? In France, accessing a system without authorization is a crime (article 323-1 of the Penal Code).", "La dirección está horrorizada: ¡explotar un fallo sin autorización es ilegal! Amonestación oficial.\n\n¿Lo sabías? Acceder a un sistema sin autorización está castigado por la ley (en España, el artículo 197 bis del Código Penal)."),
'card18_opt1_res1': ("Management pretends not to have heard…\n\nDid you know? Ethics is essential in cybersecurity: we protect, we don't attack.", "La dirección finge no haber oído nada…\n\n¿Lo sabías? La ética es esencial en ciberseguridad: se protege, no se ataca."),
'card18_opt1': ("Tell management so they can exploit it", "Contárselo a la dirección para explotarlo"),
'card18_text': ("During research, {0.SimFirstName} discovers a major flaw on another company's website.", "Durante sus investigaciones, {0.SimFirstName} descubre un fallo grave en la web de otra empresa."),
'card18_title': ("A Flaw Next Door", "Un fallo en casa del vecino"),
'card19_opt0_res0': ("The analysis shows the hacker got in through outdated software. Perfect report!\n\nDid you know? In forensics, you work on a copy so you don't damage the evidence.", "El análisis muestra que el atacante entró por un programa sin actualizar. ¡Informe perfecto!\n\n¿Lo sabías? En informática forense se trabaja sobre una copia para no dañar las pruebas."),
'card19_opt0_res1': ("The analysis is long and nothing clear comes out of it.\n\nDid you know? Centralized logs help a lot to trace what a hacker did.", "El análisis es largo y no da nada claro.\n\n¿Lo sabías? Los registros (logs) centralizados ayudan mucho a reconstruir lo que hizo un atacante."),
'card19_opt0': ("Copy the disk and analyze the copy", "Copiar el disco y analizar la copia"),
'card19_opt1_res0': ("{0.SimFirstName} erased important traces: the evidence can no longer be used.\n\nDid you know? Touching the original machine alters the evidence. Always start with a copy.", "{0.SimFirstName} ha borrado rastros importantes: las pruebas ya no sirven.\n\n¿Lo sabías? Tocar la máquina original altera las pruebas. Siempre se empieza por una copia."),
'card19_opt1_res1': ("Found quickly, but it was risky.\n\nDid you know? In forensics, the method matters as much as the result.", "Encontrado rápido, pero era arriesgado.\n\n¿Lo sabías? En informática forense, el método importa tanto como el resultado."),
'card19_opt1': ("Analyze directly on the server", "Analizar directamente en el servidor"),
'card19_text': ("A server was hacked overnight. You need to figure out how the hacker got in.", "Un servidor ha sido hackeado durante la noche. Hay que entender cómo entró el atacante."),
}
